"""V9: phrase-based reasoning, an explicit joining demonstration, and separated practice."""
from pathlib import Path
import importlib.util
import html
import json
import re

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('v8', HERE / 'build-preview-v8.py')
v8 = importlib.util.module_from_spec(spec)
spec.loader.exec_module(v8)
v7 = v8.v7
p = v7.previous

# Subject-specific design: ink #12336b, cobalt #2453df, violet #7654b8,
# mint #98ebd3, white #ffffff, ice #eef3fd. Bahnschrift headings, Segoe UI
# reading text. Separate rules are paper strips; the shared phrase forms their
# actual join. Motion follows a click, rather than decorating every paragraph.
ICONS = {
    'document': '<path d="M9 4h11l7 7v22H9zM20 4v8h7M13 18h10M13 23h10M13 28h6"/>',
    'approval': '<circle cx="18" cy="18" r="13"/><path d="m11 18 5 5 10-11M11 29l-2 7 9-4 9 4-2-7"/>',
    'signature': '<path d="m9 26 13-17 6 5-13 17-8 3zM22 9l3-4 6 5-3 4M20 34h13M8 38h25"/>',
}

def icon(name):
    return '<svg class="condition-icon" viewBox="0 0 40 42" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + ICONS[name] + '</svg>'

JOIN = '''<section class="join-demo" aria-label="Join two rules step by step"><div class="join-heading"><div><span class="teaching-label">Two rules</span><h3>Find the condition they share.</h3></div><button type="button" id="join-step">Show the matching condition</button></div><div class="join-rules"><div class="join-rule"><span class="rule-number">First rule</span><div class="join-route"><div class="join-condition">ICON_DOCUMENT<strong>Submitted late</strong></div><span class="join-arrow" aria-hidden="true">→</span><div class="join-condition matching">ICON_APPROVAL<strong>Requires special approval</strong></div></div></div><div class="join-rule"><span class="rule-number">Second rule</span><div class="join-route"><div class="join-condition matching">ICON_APPROVAL<strong>Requires special approval</strong></div><span class="join-arrow" aria-hidden="true">→</span><div class="join-condition">ICON_SIGNATURE<strong>Needs a supervisor's signature</strong></div></div></div></div><div class="join-explanation" id="join-status" aria-live="polite">Read both rules. Where the first rule ends, the second rule begins.</div><div class="join-result" id="join-result" hidden><span class="teaching-label">New rule</span><div class="join-route"><div class="join-condition">ICON_DOCUMENT<strong>Submitted late</strong></div><span class="join-arrow" aria-hidden="true">→</span><div class="join-condition">ICON_SIGNATURE<strong>Needs a supervisor's signature</strong></div></div><p>Every late application needs a supervisor's signature.</p></div><button class="join-replay" id="join-replay" type="button" hidden>Replay the connection</button><noscript><p>“Requires special approval” is the matching condition. Every late application needs a supervisor's signature.</p></noscript></section>'''
for name in ICONS:
    JOIN = JOIN.replace('ICON_' + name.upper(), icon(name))
p.base.VISUALS['JOIN-RULES'] = JOIN
p.base.VISUALS['SHARED-END'] = '''<figure class="shared-end"><div class="shared-end-inputs"><strong>Confidential file</strong><strong>Medical file</strong></div><svg viewBox="0 0 600 100" role="img" aria-label="Confidential files and medical files each lead separately to restricted storage"><path d="M120 4v24q0 20 30 20h110q40 0 40 28v18M480 4v24q0 20-30 20H340q-40 0-40 28" fill="none" stroke="currentColor" stroke-width="3"/><path d="m291 84 9 12 9-12" fill="none" stroke="currentColor" stroke-width="3"/></svg><strong class="shared-end-result">Requires restricted storage</strong><figcaption>Two arrows reach the same result. Neither arrow connects confidential files to medical files.</figcaption></figure>'''

# Older visuals used single-letter application names. Keep descriptive names
# in visual templates too, not only the Markdown text.
for key, value in list(p.base.VISUALS.items()):
    p.base.VISUALS[key] = value.replace('Application J', 'This application').replace("J's", "This application's").replace('about J', 'about this application')

p.base.VISUALS['TWO-OUTPUTS'] = p.base.VISUALS['TWO-OUTPUTS'].replace('J needs a signature.', "This application needs a supervisor's signature.").replace('Late → Needs a signature', "Submitted late → Needs a supervisor's signature")
for visual_key, visual_value in list(p.base.VISUALS.items()):
    p.base.VISUALS[visual_key] = visual_value.replace('Trained →', 'Is trained →')

class Renderer(p.Renderer):
    def prose(self, block):
        for label in ('Given rule', 'Given rules', 'Proposed conclusion', 'Possible example', 'What follows', 'Why the link fails'):
            prefix = '**' + label + ':**'
            if block.startswith(prefix):
                kind = 'possible' if label == 'Possible example' else 'claim' if label == 'Proposed conclusion' else 'given' if label in ('Given rule', 'Given rules') else 'result'
                return '<div class="reasoning-part reasoning-' + kind + '"><span class="teaching-label">' + label + '</span><p>' + p.base.inline(block[len(prefix):].strip()) + '</p></div>'
        return super().prose(block)

    def check(self, prompt, answer):
        self.checks += 1
        number = self.checks
        heading = ('Keep “some” separate from “all”.', 'Apply the file rule.', 'Separate a new rule from a new fact.', 'Use both panel rules.', 'Choose the supported move.', 'Check the approval wording.', 'Negate the whole requirement.')[number - 1]
        statements = re.split(r'(?<=[.!?])\s+', prompt)
        first_question = next((i for i, sentence in enumerate(statements) if '?' in sentence or sentence.startswith(('What ', 'Can ', 'Must ', 'Does ', 'Explain '))), len(statements))
        givens = statements[:first_question]
        questions = statements[first_question:]
        given_html = ''.join('<li>' + p.base.inline(statement) + '</li>' for statement in givens)
        question_html = ''.join('<p>' + p.base.inline(question) + '</p>' for question in questions)
        if not questions:
            question_html = '<p>' + p.base.inline(prompt) + '</p>'
            given_html = ''
        return f'''<aside class="check" data-check="{number}"><header class="check-heading"><span class="check-number">{number:02}</span><div><span class="teaching-label">Try it</span><strong>{html.escape(heading)}</strong></div><span class="check-pencil" aria-hidden="true">{icon('signature')}</span></header><div class="check-evidence">''' + ('<span class="teaching-label">Given</span><ul>' + given_html + '</ul>' if given_html else '') + f'''</div><div class="check-question">{question_html}</div><form><label for="answer-{number}">Your conclusion and reasoning</label><textarea id="answer-{number}" rows="3" required placeholder="Write what follows. Explain which fact or rule proves it."></textarea><button type="submit">Compare my reasoning</button></form><div class="feedback" hidden tabindex="-1"><span class="teaching-label">Worked answer</span><p>{p.base.inline(answer)}</p><p class="small">Compare your conclusion and reasoning with this explanation. Your writing is not automatically graded.</p><button class="again" type="button">Edit my answer</button></div><noscript><p><strong>Worked answer:</strong> {p.base.inline(answer)}</p></noscript></aside>'''

