JS = r'''
const joinDemo=document.querySelector('.join-demo'),joinStep=document.querySelector('#join-step'),joinResult=document.querySelector('#join-result'),joinReplay=document.querySelector('#join-replay'),joinStatus=document.querySelector('#join-status');
let joinStage=0;
function resetJoin(){joinStage=0;joinDemo.dataset.stage='0';joinResult.hidden=true;joinResult.classList.remove('revealed');joinReplay.hidden=true;joinStep.hidden=false;joinStep.textContent='Show the matching condition';joinStatus.textContent='Read both rules. Where the first rule ends, the second rule begins.';}
joinStep.addEventListener('click',()=>{joinStage++;joinDemo.dataset.stage=String(joinStage);if(joinStage===1){joinStatus.textContent='“Requires special approval” is the result of the first rule and the starting condition of the second. This exact match connects the rules.';joinStep.textContent='Show the new rule';}else{joinResult.hidden=false;joinResult.classList.add('revealed');joinStatus.textContent='A late application requires special approval. Anything requiring special approval needs a supervisor’s signature. So every late application needs that signature.';joinStep.hidden=true;joinReplay.hidden=false;joinReplay.focus();}});
joinReplay.addEventListener('click',()=>{resetJoin();joinStep.focus()});resetJoin();
function structurePractice(){const target=document.querySelector('#practice-prompt');const text=practice[practiceIndex].prompt;const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text];let asking=false;const givens=[],questions=[];for(const sentence of sentences){if(sentence.includes('?')||/^\s*(What|Must|Show|If |Explain)/.test(sentence))asking=true;(asking?questions:givens).push(sentence.trim());}target.replaceChildren();const list=document.createElement('ul');list.className='practice-evidence';for(const given of givens){const item=document.createElement('li');item.textContent=given;list.append(item)}const q=document.createElement('div');q.className='practice-question';for(const question of questions){const item=document.createElement('p');item.textContent=question;q.append(item)}target.append(list,q);}
structurePractice();document.querySelector('#practice-next').addEventListener('click',structurePractice);
'''

def main():
    source = (HERE / 'concept-lesson-v9.md').read_text(encoding='utf-8')
    renderer = Renderer()
    title, body = renderer.render(re.sub(r'^#### (Fact [1-4]:)', r'### \1', source, flags=re.M))
    intro = re.sub(r'\n\n\*\*(?:Fact|Rule) means:\*\* [^\n]+', '', source)
    opening = v7.opening(intro).replace('href="#section-5"', 'href="#section-4"')
    definitions = dict(re.findall(r'\*\*(Fact|Rule) means:\*\* ([^\n]+)', source))
    assert len(definitions) == 2
    opening = opening.replace('<div class="intro-methods">', '<div class="intro-definitions">' + ''.join('<div><strong>' + label + '</strong><p>' + p.base.inline(definitions[label]) + '</p></div>' for label in ('Fact', 'Rule')) + '</div><div class="intro-methods">')
    body = re.sub(r'<header class="opening">.*?</header>', lambda _: opening, body, count=1, flags=re.S)
    body = re.sub(r'<h3>(Fact [1-4]:.*?)</h3>', r'<h4>\1</h4>', body)
    # The three invalid moves form a real numbered sequence, each with distinct
    # premises, an unsupported conclusion, and a counterexample.
    body = re.sub(r'<h3>([123])\. ([^<]+)</h3>', r'<div class="invalid-move"><h3><span class="invalid-number">\1</span><span>\2</span></h3>', body)
    for boundary in ('<div class="invalid-move"><h3><span class="invalid-number">2', '<div class="invalid-move"><h3><span class="invalid-number">3'):
        body = body.replace(boundary, '</div>' + boundary, 1)
    body = body.replace('<h3>Check the whole condition before linking</h3>', '</div><h3>Check the whole condition before linking</h3>', 1)
    nav = '<nav class="jump" aria-label="Lesson sections">' + ''.join(f'<a href="#section-{n}">{label}</a>' for n,label in [(1,'Facts'),(2,'Rules'),(3,'Apply'),(4,'Link'),(5,'Add a fact'),(6,'Invalid moves'),(7,'Contrapose'),(8,'Wording'),(10,'Practice')]) + '</nav>'
    body = re.sub(r'<nav class="jump".*?</nav>', lambda _: nav, body, count=1, flags=re.S)
    body = body.replace('Name the move. Explain what the statements guarantee.', 'Write your conclusion and the rule or chain that proves it.').replace('<h2>Follow the fact.</h2>', '<h3>What does this fact let you conclude?</h3>').replace('<span class="eyebrow">Use the moves</span>', '<span class="eyebrow">Conditional reasoning practice</span>')
    body = body.replace('<p id="practice-prompt"></p>', '<div id="practice-prompt"></div>')
    # Ensure conditions remain in ordinary teaching typography throughout.
    body = body.replace('Application J', 'This application').replace("J's", "This application's").replace('about J', 'about this application')
    assert renderer.checks == 7 and len(renderer.practice) == 4
    data = json.dumps(renderer.practice, ensure_ascii=False).replace('<', '\\u003c')
    body = '<section class="hero"><h1 class="lesson-title"><span>Facts,</span><span>Rules,</span><span>and What Follows</span></h1>' + body.replace('</header>', '</header></section>', 1)
    old_js = p.base.JS.replace('Late →', 'Submitted late →')
    extra_js = p.EXTRA_JS.replace('Late →', 'Submitted late →').replace('Correct. The direction matters.', 'Correct. A shared starting condition does not connect the two results.')
    page = f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="lsatu-interactive-lesson" content="yahunatan-2026-09-16-conditional-reasoning"><title>{html.escape(title)} | LSAT U</title><style>{p.CSS}{p.HERO_CSS}{p.READING_CSS}{p.V6_CSS}{v7.CSS}{CSS}</style></head><body><header class="top"><b>LSAT U</b><div class="top-right"><span>Notes and recaps</span><button type="button" id="motion-toggle" aria-pressed="false">Pause motion</button></div></header><main class="lesson-shell">{body}</main><script>const practice={data};{old_js}{extra_js}{JS}</script></body></html>'
    for rejected in ['Let <strong>T</strong>', 'T → B', 'without adding a case', 'concept lesson', '\u2014', 'Application J', 'Instructor Q', 'Visitor S', 'Expense E', 'J needs']:
        assert rejected not in page, rejected
    assert not re.search(r'\b[A-Z]\s*(?:→|←)', page), 'Single-letter condition remains'
    assert len(page.encode('utf-8')) < 500_000
    ids = re.findall(r'\bid="([^"]+)"', page)
    assert len(ids) == len(set(ids)), 'Duplicate ids'
    assert all(anchor in ids for anchor in re.findall(r'href="#([^"]+)"', page)), 'Broken anchor'
    output = HERE / 'conditional-reasoning-v9.html'
    output.write_text(page, encoding='utf-8')
    print(f'{output}\nChecks: {renderer.checks}; mixed: {len(renderer.practice)}; bytes: {len(page.encode("utf-8"))}')

if __name__ == '__main__':
    main()
